<?php namespace App\Http\Middleware; use App\Models\Admin;use App\Support\Jwt;use Closure;use Illuminate\Http\Request;class JwtAuth{function handle(Request $r,Closure $n){if(!$r->bearerToken())return response()->json(['error'=>'Token is missing'],401);$p=Jwt::read($r->bearerToken());$a=$p?Admin::find($p['user_id']??null):null;if(!$a)return response()->json(['error'=>'Invalid or expired token'],401);$r->attributes->set('admin',$a);return $n($r);}}
